--
-- Table structure for table `egame`
--

DROP TABLE IF EXISTS `egame`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `egame` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `game_type` tinyint unsigned DEFAULT '0' COMMENT '类型 4:电游 5:捕鱼 7:棋牌',
  `game_code` varchar(16) DEFAULT NULL COMMENT '游戏场馆编码',
  `web_code` varchar(32) DEFAULT '' COMMENT 'WEB游戏编号',
  `h5_code` varchar(32) DEFAULT NULL COMMENT 'H5游戏编号',
  `cn_name` varchar(32) DEFAULT '' COMMENT '中文名称',
  `en_name` varchar(32) DEFAULT '' COMMENT '英文名称',
  `web_img_url` varchar(128) DEFAULT '' COMMENT 'WEB图片地址',
  `h5_img_url` varchar(128) DEFAULT '' COMMENT 'H5图片地址',
  `is_online` tinyint(1) DEFAULT '1' COMMENT '是否上线 1:是 2:否',
  `is_hot` tinyint(1) DEFAULT '2' COMMENT '是否热门 1:是 2:否',
  `is_new` tinyint(1) DEFAULT '2' COMMENT '是否最新 1:是 2:否',
  `is_h5` tinyint(1) DEFAULT '1' COMMENT '是否H5 1:是 2:否',
  `mode` tinyint(1) DEFAULT '1' COMMENT '模式 1:竖屏模式 2:横屏模式',
  `sort` int DEFAULT '0' COMMENT '排序',
  `created_at` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` tinyint(1) DEFAULT '1' COMMENT '游戏状态 1完成 0下线',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

